// === Tab: mySketch ===
/**
 * Leaves
 * For the #WCCChallenge << Botanical >> (join the discord! https://discord.gg/S8c7qcjw2b)
 *
 * Tried to generate leaves on this sketch without using a fractal function, and using easing functions
 * combined to determine the shape. Rampensau for generating some color palettes, and some light circle
 * packing to determine the position of the leaves
 */

let cw, ch
let nLeaves
let leafConfigs = []
let leafPoints = []
let maxFrames = 480
let startFrame = 0
let circlePositions
let easeInCirc = t => 1 - sqrt(1 - t * t)
let easeInExpo = t => t == 0 ? 0 : pow(2, 10 * (t - 1))
let easeInBack = t => t * t * ((1.70158 + 1) * t - 1.70158)
let easeInQuad = t => t * t
let easeOutQuint = t => 1 + (--t) * t * t * t * t
let easeOutSine = t => sin(t * PI / 2)
let easeOutCubic = t => 1 + (--t) * t * t

let easeInFunctions = [
  easeInCirc, easeInExpo, easeInBack, easeInQuad
]
let easeOutFunctions = [
  easeOutQuint, easeOutSine, easeOutCubic
]

function setup () {
  cw = windowWidth
  ch = windowHeight
  createCanvas(cw, ch)
  background(255)
  colorMode(HSL, 360, 1, 1, 1)
  noFill()
  initializeConfig()
}

let initializeConfig = () => {
  startFrame = frameCount
  circlePositions = getCirclePos()
  nLeaves = circlePositions.length
  for (let i = 0; i < nLeaves; i++) {
    // Pick random combinations of out, in, out functions
    let fn1 = random(easeOutFunctions)
    let fn2 = random(easeInFunctions)
    let fn3 = random(easeOutFunctions)
    let fn4 = random(easeInFunctions)

    let len = circlePositions[i].d * random(1.2, 1.5) // Inexact packing
    let rotation = noise(circlePositions[i].x * 0.01, circlePositions[i].y * 0.05) * TAU // Use flow field
    let startPos = [
      circlePositions[i].x,
      circlePositions[i].y + random(len / 4)
    ]

    let ramp = rampensau.generateColorRamp({
      total: 4,
      hStart: floor(random(360)),
      hCycles: random(0.3, 0.6),
      hEasing: random(easeInFunctions),
      sRange: [random(0.4, 0.7), random(0.2, 0.4)],
      lRange: [random(0.4, 0.6), random(0.2, 0.8)],
      lEasing: random(easeInFunctions),
    })
    let palette = ramp.map((c) => color(...c).toString('#rrggbb'))
    leafConfigs.push({
      size: len,
      fn1, fn2, fn3, fn4,
      startAngle: -PI/2 + random(-PI/16, PI/16),
      curveFactor: random(0.5, 1),
      initialWobble: random(1000),
      bendSeed: random(10),
      jitter: random(5, 20),
      startPos,
      rotation,
      palette,
      points: [],
			maxNoise: len/random(10,15),
			minNoise: len/random(15,20)
    })
    leafPoints.push([])
  }
  bgColor = color(random(360), random(0.1, 0.3), random(0.9, 1)).toString('#rrggbb')
  background(bgColor)
  stroke('#00000080')
  for (let c of circlePositions) {
    circle(c.x, c.y, c.d)
  }
}

function draw () {
  if (frameCount > startFrame + maxFrames) {
    background(bgColor)
    for (let i = 0; i < leafPoints.length; i++) {
      let leaf = leafPoints[i]
      let leafConfig = leafConfigs[i]
      var len = leafConfig.size
      push()
      translate(...leafConfig.startPos)
      rotate(leafConfig.rotation)

      strokeWeight(3)
      stroke(leafConfig.palette[0])
      for (let j = 0; j < leaf.length; j++) {
        line(...leaf[j][0], ...leaf[j][1])
        line(...leaf[j][1], ...leaf[j][2])
      }

      let sp = random(0.05, 0.1)
      stroke(leafConfig.palette[1] + '80')
      for (let j = 0; j < leaf.length; j++) {
        let s = sin(j * sp)
        s = map(s, -1, 1, 0.2, 0.8)
        s = s * map(wobbly(s, 100), 0, 1, 0.8, 1.2)
        s = s + map(noise(j * 0.1), 0, 1, -0.2, 0.2)
        line(
          ...leaf[j][1],
          ...lerpLine(leaf[j][1], leaf[j][2], s)
        )
        line(
          ...leaf[j][1],
          ...lerpLine(leaf[j][1], leaf[j][0], s)
        )
      }

      let sp2 = random(0.01, 0.3)
      stroke(leafConfig.palette[2] + '80')
      for (let j = 0; j < leaf.length; j++) {
        var s = sin(j * sp2)
        s = map(s, -1, 1, 0.2, 0.8)
        s = s * map(wobbly(s, 100), 0, 1, 0.8, 1.2)
        s = s + map(noise(j * 0.1), 0, 1, -0.2, 0.2)
        line(
          ...leaf[j][1],
          ...lerpLine(leaf[j][1], leaf[j][2], s)
        )
        line(
          ...leaf[j][1],
          ...lerpLine(leaf[j][1], leaf[j][0], s)
        )
      }

      stroke(leafConfig.palette[3] + '40')
      for (let j = 0; j < leaf.length; j++) {
        if (random() < 0.1) {
          let target = random() < 0.5 ? leaf[j][0] : leaf[j][2]
          strokeWeight(random(0.5, 2))
          drawWobblyLine(
            leaf[j][1],
            lerpLine(leaf[j][1], target, random(0.3, 0.6)),
            5,
            len/100
          )
        }
      }
      pop()
    }
    // noLoop() removed for animationreturn
  }
  let p = (frameCount - startFrame) / maxFrames
  for (let i = 0; i < nLeaves; i++) {
    let leafLength = leafConfigs[i].size
    let h = leafLength
    let minLen = 0
    let maxLen = h / 2
    var leafConfig = leafConfigs[i]
    push()
    let leafP = leafPoints[i]
    translate(...leafConfig.startPos)
    rotate(leafConfig.rotation)
    strokeWeight(5)
    getLeafPoints(p, leafLength, minLen, maxLen, leafConfig, leafP)
    pop()
  }
}

// On click regenerate
function mouseClicked () {
  leafConfigs = []
  leafPoints = []
  background(bgColor)
  initializeConfig()
  loop()
}

/*
  The magic happens here. Now I don't even know what's going on, but the gist is:
  traverse over the "stem" of the leaf, and using easing functions, calculate the rotation
  and length of the leaf (this can be seen on the initial animation phase as it draws the lines)
  The randomness of the leaves comes from the easing functions to use, and some wobble to the stem itself
*/
let getLeafPoints = (p, leafLength, minLen, maxLen, leafConfig, leafPoints) => {
  let {fn1, fn2, fn3, fn4, startAngle, curveFactor, initialWobble, bendSeed, maxNoise, minNoise} = leafConfig
  let nf = 0.08 // Pass as parameter later
  stroke(leafConfig.palette[0])
  let angle = map(fn1(p), 0, 1, startAngle, PI/2)
  var startPos = map(fn4(p), 0, 1, 0, leafLength / 2)
  let x = map(noise(bendSeed + p * leafConfig.jitter), 0, 1, -maxLen/10, maxLen/10)
  let f = mul(fn2, inv(fn3))
  f = mul(fn3, inv(easeInCirc))
  var len = map(f(p), 0, 1, minLen, maxLen)
  var s = sin(PI * p * curveFactor)
  len = len * s
  let nLen = len + map(noise(p * nf), 0, 1, minNoise, maxNoise)
  let wobbliness = wobbly(p, initialWobble + frameCount * nf) * (maxNoise - minNoise) / 10
  nLen = nLen + wobbliness
  let middle = [x, startPos]
  let left = [nLen * cos(angle) + x, startPos + nLen * sin(angle)]
  let right = [-nLen * cos(angle) + x, startPos + nLen * sin(angle)]
  leafPoints.push([left, middle, right])
  // Draw the leaf while collecting the points
  line(...middle, ...left)
  line(...middle, ...right)
  leafConfig.points.push([left, middle, right])
  return leafPoints
}

// Pseudo circle packing, tries to fill in the space with a limited number of tries
let getCirclePos = () => {
  let circles = []
  let minDimension = max(width, height)
  let maxRadius = minDimension / 6
  let minRadius = minDimension / 40

  let _wG_1 = 0; while ((maxRadius >= minRadius) && ++_wG_1 < 20000) {
    let newCircle = createCircle(maxRadius, circles)
    if (newCircle !== null) {
      circles.push(newCircle)
    }
    maxRadius *= 0.98
  }
  return circles
}

let createCircle = (radius, circles, overlapMargin = 0.6) => {
  let safe = false
  var x, y
  for (let tries = 0; tries < 5000; tries++) { // Tries to place a circle without overlapping
    x = random(radius * overlapMargin, cw - radius * overlapMargin)
    y = random(radius * overlapMargin, ch - radius * overlapMargin)
    safe = true
    for (let other of circles) {
      let d = dist(x, y, other.x, other.y)
      if (d < (radius + other.radius) * overlapMargin) {
        safe = false
        break
      }
    }
    if (safe) {
      return { x: x, y: y, radius: radius, d: radius * 2 }
    }
  }
  return null
}

// --- Utils ---

// I like functions
let inv = (fn) => { return t => 1 - fn(1 - t) }
let mul = (fn1, fn2) => { return t => fn1(t) * fn2(t) }

let lerpLine = (p0, p1, n) => {
  return [
    lerp(p0[0], p1[0], n),
    lerp(p0[1], p1[1], n)
  ]
}

let wobbly = (x, t) => {
  return sin(1.2*x - 1*t + 1 + 2*sin(2*x + 1.3*t + 5)**3)
}

let wobblyLine = (p1, p2, segmentLength = 10, wobbleRange = 5) => {
  let [x1, y1] = p1
  let [x2, y2] = p2
  let points = [];
  let dx = x2 - x1
  let dy = y2 - y1
  let lineLength = dist(x1, y1, x2, y2)
  let numSegments = lineLength / segmentLength
  let dirX = dx / lineLength
  let dirY = dy / lineLength
  let perpX = -dirY
  let perpY = dirX

  for (let i = 0; i <= numSegments; i++) {
    let segmentX = x1 + dirX * segmentLength * i
    let segmentY = y1 + dirY * segmentLength * i
    let wobbleOffset = map(noise(i * 0.5), 0, 1, -wobbleRange, wobbleRange) // Use noise to create a smooth wobble
    let wobbleX = segmentX + perpX * wobbleOffset
    let wobbleY = segmentY + perpY * wobbleOffset

    points.push([wobbleX, wobbleY])
  }

  return points
}

let drawWobblyLine = (p1, p2, segmentLength = 10, wobbleRange = 5) => {
  var points = wobblyLine(p1, p2, segmentLength, wobbleRange)
  beginShape()
  for (let p of points) {
    vertex(...p)
  }
  endShape()
}

